<script setup>
import { computed, ref } from 'vue';
import { Link, useForm, router, usePage } from '@inertiajs/vue3';
import { route } from 'ziggy-js';
import { Plus, ArrowUpRight, Users, FileText, Wallet, CalendarDays, X, Download, Check } from 'lucide-vue-next';
import CorporateLayout from '../Components/Shared/CorporateLayout.vue';
const props = defineProps({ company: Object, memberRole: String, requests: Object, members: Object, stats: Object, filter: String });
const page = usePage();
const section = ref('overview');
const newDialog = ref(null);
const detailDialog = ref(null);
const selected = ref(null);
const money = value => new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value || 0);
const dateLabel = value => value ? new Intl.DateTimeFormat('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value)) : '—';
const quoteExpired = computed(() => selected.value?.quote_expires_at && new Date(selected.value.quote_expires_at).getTime() <= Date.now());
const labels = {submitted:'Menunggu penawaran',quoted:'Perlu persetujuan',approved:'Siap dipesan',rejected:'Ditolak',booked:'Sudah dipesan',cancelled:'Dibatalkan'};
const roles = {owner:'Pemilik workspace',requester:'PIC / pengaju',approver:'Approver',finance:'Finance'};
const paymentLabels = {awaiting_payment:'Menunggu pembayaran',paid:'Lunas',confirmed:'Dikonfirmasi vendor',ongoing:'Sedang berlangsung',completed:'Selesai',expired:'Reservasi berakhir',cancelled:'Dibatalkan',refunded:'Dana dikembalikan'};
const canRequest = computed(() => ['owner','requester'].includes(props.memberRole));
const canDecide = computed(() => ['owner','approver'].includes(props.memberRole));
const canPay = computed(() => ['owner','finance'].includes(props.memberRole));
const form = useForm({title:'',destination:'',departure_date:'',end_date:'',participants:10,budget:10000000,cost_center:'',needs:'',idempotency_key:crypto.randomUUID()});
const invite = useForm({email:'',role:'requester'});
const policy = useForm({monthly_limit:props.company.monthly_limit || ''});
const decision = useForm({decision:'approved',note:''});
const book = useForm({});
const cancel = useForm({});
function resubmit() { for(const key of ['title','destination','participants','budget','cost_center','needs']) form[key]=selected.value[key]; form.departure_date=selected.value.departure_date.slice(0,10);form.end_date=selected.value.end_date.slice(0,10);form.idempotency_key=crypto.randomUUID();detailDialog.value.close();newDialog.value.showModal(); }
const roster = useForm({travelers:[]});
const rosterNames = ref('');
function saveRoster() { roster.travelers = rosterNames.value.split('\n').map(name=>name.trim()).filter(Boolean).map(name=>({name})); roster.patch(route('corporate.requests.travelers',selected.value.id),{onSuccess:()=>detailDialog.value.close()}); }
function submit() { form.post(route('corporate.requests.store',props.company.id),{onSuccess:()=>{newDialog.value.close();form.reset();form.idempotency_key=crypto.randomUUID();}}); }
function show(item) { selected.value=item;rosterNames.value=(item.travelers || []).map(person=>person.name).join('\n');roster.clearErrors();decision.reset();decision.clearErrors();book.clearErrors();cancel.clearErrors();detailDialog.value.showModal(); }
function decide(value) { decision.decision=value;decision.post(route('corporate.requests.decide',selected.value.id),{onSuccess:()=>detailDialog.value.close()}); }
const tabs = computed(()=> [{key:'overview',label:'Ringkasan',icon:CalendarDays},{key:'requests',label:'Pengajuan & pesanan',icon:FileText},...(props.memberRole==='owner'?[{key:'team',label:'Tim & akses',icon:Users},{key:'policy',label:'Kebijakan anggaran',icon:Wallet}]:[])]);
</script>
<template>
<CorporateLayout title="Workspace perusahaan" :company="company"><div class="grid gap-8 lg:grid-cols-[220px_1fr]"><aside><div class="border-b border-slate-200 pb-6"><p class="text-[10px] font-bold uppercase tracking-widest text-slate-500">Workspace</p><h1 class="mt-3 text-xl leading-7 font-bold">{{ company.name }}</h1><span class="mt-3 inline-flex rounded border px-2 py-1 text-[10px] font-semibold" :class="company.status==='verified'?'border-emerald-200 bg-emerald-50 text-emerald-800':'border-amber-200 bg-amber-50 text-amber-900'">{{ company.status==='verified'?'Perusahaan aktif':company.status==='pending'?'Dalam verifikasi':company.status==='suspended'?'Akses dibatasi':'Pengajuan ditolak' }}</span><p class="mt-3 text-xs text-slate-500">{{ roles[memberRole] }}</p></div><nav class="mt-5 flex flex-wrap gap-1 lg:flex-col" aria-label="Menu workspace"><button v-for="tab in tabs" :key="tab.key" class="flex items-center gap-3 rounded-lg px-4 py-3 text-left text-sm font-medium" :class="section===tab.key?'bg-white text-[#0088ff] ring-1 ring-slate-200':'text-slate-500 hover:bg-white'" :aria-current="section===tab.key?'page':undefined" @click="section=tab.key"><component :is="tab.icon" class="size-4" />{{ tab.label }}</button></nav><a v-if="memberRole!=='requester'" :href="route('corporate.report',company.id)" class="mt-7 inline-flex items-center gap-2 text-xs font-semibold"><Download class="size-4" /> Unduh laporan CSV</a></aside>
<div class="min-w-0"><div v-if="company.status!=='verified'" class="mb-7 rounded-lg border border-amber-200 bg-amber-50 p-5"><h2 class="font-semibold">{{ company.status==='pending'?'Registrasi diterima. Menunggu verifikasi.':'Perusahaan belum dapat melakukan pemesanan.' }}</h2><p class="mt-2 text-sm leading-6 text-amber-900">{{ company.verification_note || 'Tim operasional meninjau data perusahaan. Kamu sudah bisa mengundang tim sambil menunggu aktivasi.' }}</p></div>
<template v-if="['overview','requests'].includes(section)"><div class="flex flex-wrap items-end justify-between gap-5"><div><p class="text-xs text-slate-500">{{ section==='overview'?'Pusat kendali perjalanan':'Daftar kebutuhan perusahaan' }}</p><h2 class="mt-2 text-3xl font-bold tracking-tight">{{ section==='overview'?'Perjalanan tim, dalam kendali.':'Pengajuan & pesanan' }}</h2></div><button v-if="canRequest" :disabled="company.status!=='verified'" class="panel-primary" @click="newDialog.showModal()"><Plus class="mr-2 size-4" />Ajukan perjalanan</button></div>
<div v-if="section==='overview'" class="mt-7 grid divide-y divide-slate-200 rounded-xl border border-slate-200 bg-white sm:grid-cols-4 sm:divide-x sm:divide-y-0"><div v-for="stat in [{label:'Perlu ditindaklanjuti',value:stats.waiting},{label:'Siap dipesan',value:stats.approved},{label:'Total pesanan',value:stats.booked},{label:'Pembayaran terkonfirmasi',value:money(stats.paid)}]" :key="stat.label" class="p-5"><p class="text-xs leading-5 text-slate-500">{{ stat.label }}</p><p class="mt-3 text-2xl font-bold tracking-tight">{{ stat.value }}</p></div></div>
<div class="mt-8 rounded-xl border border-slate-200 bg-white"><div class="flex flex-wrap items-center justify-between gap-4 border-b border-slate-200 p-5"><h3 class="font-semibold">{{ section==='overview'?'Aktivitas perjalanan':'Semua pengajuan' }}</h3><select :value="filter" aria-label="Filter status pengajuan" class="rounded-lg border border-slate-200 px-3 py-2 text-xs" @change="router.get(route('corporate.workspace',company.id),{status:$event.target.value},{preserveState:true})"><option value="">Semua status</option><option v-for="(label,key) in labels" :key="key" :value="key">{{ label }}</option></select></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-[11px] text-slate-500"><tr><th scope="col" class="p-5 font-medium">Kegiatan / pengaju</th><th scope="col" class="p-5 font-medium">Jadwal & peserta</th><th scope="col" class="p-5 font-medium">Penawaran</th><th scope="col" class="p-5 font-medium">Status</th><th scope="col" class="p-5"></th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="item in requests.data" :key="item.id"><td class="p-5"><p class="font-semibold">{{ item.title }}</p><p class="mt-2 text-xs text-slate-500">{{ item.requester.name }} · {{ item.cost_center }}</p></td><td class="whitespace-nowrap p-5"><p>{{ dateLabel(item.departure_date) }}</p><p class="mt-2 text-xs text-slate-500">{{ item.participants }} peserta · {{ item.destination }}</p></td><td class="whitespace-nowrap p-5 font-semibold">{{ item.quote_total ? money(item.quote_total) : 'Belum tersedia' }}</td><td class="p-5"><span class="whitespace-nowrap rounded bg-slate-100 px-2 py-1 text-[11px] font-medium">{{ labels[item.status] }}</span><p v-if="item.booking" class="mt-2 text-xs text-slate-500">{{ paymentLabels[item.booking.status] || item.booking.status }}</p></td><td class="p-5"><button class="inline-flex items-center gap-1 text-xs font-bold text-[#0088ff]" :aria-label="'Detail '+item.title" @click="show(item)">Detail <ArrowUpRight class="size-4" /></button></td></tr></tbody></table></div><div v-if="!requests.data.length" class="px-6 py-14 text-center"><FileText class="mx-auto size-7 text-slate-300" /><h3 class="mt-4 font-semibold">Belum ada pengajuan pada daftar ini</h3><p class="mt-2 text-sm text-slate-500">Ajukan kebutuhan, kemudian bandingkan penawaran sebelum persetujuan.</p></div><nav class="flex justify-between border-t border-slate-100 p-5 text-xs" aria-label="Halaman pengajuan"><Link v-if="requests.prev_page_url" :href="requests.prev_page_url" preserve-state>Sebelumnya</Link><Link v-if="requests.next_page_url" :href="requests.next_page_url" preserve-state>Berikutnya</Link></nav></div><p class="mt-5 text-xs leading-6 text-slate-500">Pengajuan → penawaran → persetujuan → pemesanan & pembayaran → pelaksanaan. Penawaran tidak mereservasi kuota.</p></template>
<section v-if="section==='team'" class="rounded-xl border border-slate-200 bg-white p-6"><h2 class="text-2xl font-bold">Tim & akses</h2><p class="mt-3 text-sm leading-6 text-slate-500">Undang akun TapakLokal yang sudah terdaftar. Penerima menerima undangan dari menu Perusahaan saya. Pengaju dan approver harus orang yang berbeda.</p><form class="mt-7 grid gap-4 sm:grid-cols-[1fr_200px_auto]" @submit.prevent="invite.post(route('corporate.members.invite',company.id),{onSuccess:()=>invite.reset()})"><label class="text-xs font-semibold">Email akun<input v-model="invite.email" required type="email" class="panel-input mt-2" /></label><label class="text-xs font-semibold">Peran<select v-model="invite.role" class="panel-input mt-2"><option value="requester">PIC / pengaju</option><option value="approver">Approver</option><option value="finance">Finance</option></select></label><button :disabled="invite.processing" class="panel-primary self-end">Undang anggota</button></form><p v-for="error in invite.errors" :key="error" role="alert" class="mt-3 text-sm text-red-700">{{ error }}</p><article v-for="member in members?.data" :key="member.id" class="mt-5 flex items-center justify-between gap-4 border-t border-slate-100 pt-5"><div><p class="font-semibold">{{ member.user.name }}</p><p class="mt-2 text-xs text-slate-500">{{ member.user.email }} · {{ roles[member.role] }} · {{ member.status==='active'?'Aktif':'Menunggu penerimaan' }}</p></div><button v-if="member.role!=='owner'" class="text-xs font-semibold text-red-700" @click="router.delete(route('corporate.members.remove',{company:company.id,membership:member.id}))">Cabut akses</button></article><nav class="mt-6 flex gap-4 text-xs"><Link v-if="members?.prev_page_url" :href="members.prev_page_url" preserve-state>Sebelumnya</Link><Link v-if="members?.next_page_url" :href="members.next_page_url" preserve-state>Berikutnya</Link></nav></section>
<section v-if="section==='policy'" class="max-w-2xl rounded-xl border border-slate-200 bg-white p-7"><h2 class="text-2xl font-bold">Kebijakan anggaran</h2><p class="mt-3 text-sm leading-7 text-slate-500">Batas bulanan dihitung menurut bulan keberangkatan. Penawaran yang disetujui dan pesanan aktif menggunakan anggaran. Pesanan batal, kedaluwarsa, atau refund tidak dihitung.</p><form class="mt-7" @submit.prevent="policy.put(route('corporate.policy',company.id))"><label class="text-sm font-semibold">Batas anggaran bulanan (Rp)<input v-model="policy.monthly_limit" type="number" min="100000" max="10000000000" class="panel-input mt-3" /></label><p class="mt-2 text-xs text-slate-500">Kosongkan jika perusahaan tidak menetapkan batas bulanan.</p><p v-for="error in policy.errors" :key="error" role="alert" class="mt-3 text-sm text-red-700">{{ error }}</p><button :disabled="policy.processing" class="panel-primary mt-5">Simpan kebijakan</button></form></section>
</div></div>
<dialog ref="newDialog" aria-labelledby="corporate-request-title" class="m-auto max-h-[90vh] w-[min(720px,calc(100%-32px))] overflow-y-auto rounded-xl bg-white p-0 text-[#173451] backdrop:bg-slate-950/40"><div class="flex items-center justify-between border-b border-slate-200 p-6"><h2 id="corporate-request-title" class="text-xl font-bold">Ajukan perjalanan tim</h2><button type="button" aria-label="Tutup formulir" @click="newDialog.close()"><X class="size-5" /></button></div><form class="p-6" @submit.prevent="submit"><div class="grid gap-5 sm:grid-cols-2"><label v-for="(label,key) in {title:'Nama kegiatan',destination:'Destinasi',departure_date:'Tanggal berangkat',end_date:'Tanggal selesai',participants:'Jumlah peserta',budget:'Batas anggaran kegiatan (Rp)',cost_center:'Departemen / cost center'}" :key="key" class="text-xs font-semibold">{{ label }}<input v-model="form[key]" required :type="key.includes('date')?'date':['participants','budget'].includes(key)?'number':'text'" :min="key==='participants'?1:key==='budget'?1000:undefined" :max="key==='participants'?1000:undefined" class="panel-input mt-2" /></label><label class="text-xs font-semibold sm:col-span-2">Kebutuhan kegiatan<textarea v-model="form.needs" required minlength="10" maxlength="10000" rows="4" placeholder="Tujuan gathering, titik kumpul, transportasi, konsumsi, kebutuhan aksesibilitas, atau paket oleh-oleh…" class="panel-input mt-2"></textarea></label></div><p v-for="error in form.errors" :key="error" role="alert" class="mt-3 text-sm text-red-700">{{ error }}</p><button :disabled="form.processing" class="panel-primary mt-6 w-full justify-center">Kirim pengajuan</button></form></dialog>
<dialog ref="detailDialog" aria-labelledby="corporate-detail-title" class="m-auto max-h-[90vh] w-[min(760px,calc(100%-32px))] overflow-y-auto rounded-xl bg-white p-0 text-[#173451] backdrop:bg-slate-950/40"><template v-if="selected"><div class="flex items-start justify-between gap-5 border-b border-slate-200 p-6"><div><p class="text-[10px] text-slate-500">{{ selected.reference }}</p><h2 id="corporate-detail-title" class="mt-2 text-xl font-bold">{{ selected.title }}</h2></div><button aria-label="Tutup detail" @click="detailDialog.close()"><X class="size-5" /></button></div><div class="p-6"><dl class="grid grid-cols-2 gap-5 text-sm"><div><dt class="text-xs text-slate-500">Pengaju</dt><dd class="mt-2">{{ selected.requester.name }}</dd></div><div><dt class="text-xs text-slate-500">Jadwal</dt><dd class="mt-2">{{ dateLabel(selected.departure_date) }} – {{ dateLabel(selected.end_date) }}</dd></div><div><dt class="text-xs text-slate-500">Peserta</dt><dd class="mt-2">{{ selected.participants }} orang</dd></div><div><dt class="text-xs text-slate-500">Anggaran pengajuan</dt><dd class="mt-2">{{ money(selected.budget) }}</dd></div></dl><p class="mt-6 whitespace-pre-line text-sm leading-7">{{ selected.needs }}</p><p v-if="quoteExpired && !selected.booking_id" role="status" class="mt-6 rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm leading-6 text-amber-900">Masa berlaku penawaran sudah berakhir. Tim operasional perlu memperbarui penawaran sebelum persetujuan dan pemesanan dapat dilanjutkan.</p><section v-if="selected.quote" class="mt-6 rounded-lg border border-slate-200 p-5"><p class="text-xs text-slate-500">Penawaran versi {{ selected.quote.version }} · berlaku sampai {{ dateLabel(selected.quote_expires_at) }}</p><h3 class="mt-3 font-bold">{{ selected.quote.title }}</h3><p class="mt-2 text-xs text-slate-500">{{ selected.quote.vendor }}</p><p class="mt-5 text-2xl font-bold">{{ money(selected.quote_total) }}</p><p class="mt-2 text-xs text-slate-500">{{ money(selected.quote.unit_price) }} × {{ selected.participants }} peserta · pembayaran penuh melalui Midtrans</p><h4 class="mt-6 text-xs font-bold uppercase tracking-wide">Rencana perjalanan</h4><p class="mt-2 whitespace-pre-line text-sm leading-7">{{ typeof selected.quote.itinerary==='string'?selected.quote.itinerary:JSON.stringify(selected.quote.itinerary) }}</p><h4 class="mt-6 text-xs font-bold uppercase tracking-wide">Fasilitas & ketentuan</h4><p class="mt-2 whitespace-pre-line text-sm leading-7">{{ selected.quote.terms }}</p><p class="mt-5 text-xs text-slate-500">Kuota diperiksa kembali saat pemesanan. Ini penawaran kegiatan, bukan e-Faktur pajak.</p></section><section class="mt-6 border-t border-slate-200 pt-5"><h3 class="font-semibold">Daftar peserta · {{ selected.travelers?.length || 0 }}/{{ selected.participants }}</h3><form v-if="canRequest && !selected.booking_id" class="mt-4" @submit.prevent="saveRoster"><label class="text-xs font-semibold">Nama lengkap peserta, satu nama per baris<textarea v-model="rosterNames" required rows="5" class="panel-input mt-2" /></label><p class="mt-2 text-xs text-slate-500">Daftar dikirim ke vendor saat pesanan dibuat. Lengkapi sebelum finance melanjutkan pembayaran.</p><p v-for="error in roster.errors" :key="error" role="alert" class="mt-3 text-sm text-red-700">{{ error }}</p><button :disabled="roster.processing" class="panel-secondary mt-4">Simpan daftar peserta</button></form><ol v-else class="mt-3 list-inside list-decimal space-y-2 text-xs text-slate-500"><li v-for="(person,index) in selected.travelers" :key="index">{{ person.name }}</li></ol></section><p v-if="selected.decision_note" class="mt-5 text-sm">Keputusan: {{ selected.decision_note }}</p><form v-if="selected.status==='quoted' && !quoteExpired && canDecide && selected.user_id!==page.props.auth.user.id" class="mt-6" @submit.prevent="decide('approved')"><label class="text-sm font-semibold">Catatan keputusan<textarea v-model="decision.note" required minlength="5" maxlength="2000" class="panel-input mt-2" /></label><div class="mt-4 flex gap-3"><button :disabled="decision.processing" class="panel-primary">Setujui penawaran</button><button type="button" :disabled="decision.processing" class="panel-secondary" @click="decide('rejected')">Tolak</button></div></form><p v-else-if="selected.status==='quoted' && !quoteExpired" class="mt-6 text-sm text-slate-500">Menunggu approver perusahaan. Pengaju tidak dapat menyetujui pengajuannya sendiri.</p><button v-if="canPay && (selected.status==='approved' || selected.booking?.status==='awaiting_payment')" :disabled="book.processing || (!selected.booking_id && (quoteExpired || selected.travelers?.length!==selected.participants))" class="panel-primary mt-6 w-full justify-center" @click="book.post(route('corporate.requests.book',selected.id))">{{ selected.booking?'Lanjutkan pembayaran':'Pesan & lanjut ke pembayaran' }}</button><p v-if="selected.booking" class="mt-5 text-sm">Pesanan {{ selected.booking.reference }} · {{ paymentLabels[selected.booking.status] }}</p><button v-if="canRequest && (['rejected','cancelled'].includes(selected.status) || ['expired','cancelled'].includes(selected.booking?.status))" class="panel-secondary mt-5" @click="resubmit">Ajukan ulang kegiatan</button><button v-if="(canPay || (canRequest && selected.user_id===page.props.auth.user.id)) && (['submitted','quoted','approved'].includes(selected.status) || selected.booking?.status==='awaiting_payment')" :disabled="cancel.processing" class="mt-5 block text-xs font-semibold text-red-700" @click="cancel.post(route('corporate.requests.cancel',selected.id),{onSuccess:()=>detailDialog.close()})">Batalkan pengajuan / reservasi</button><p v-for="error in {...decision.errors,...book.errors,...cancel.errors}" :key="error" role="alert" class="mt-3 text-sm text-red-700">{{ error }}</p><details v-if="selected.quote_history?.length>1" class="mt-6 text-sm"><summary class="cursor-pointer font-semibold">Riwayat penawaran</summary><p v-for="quote in selected.quote_history" :key="quote.version" class="mt-3 text-xs text-slate-500">Versi {{ quote.version }} · {{ money(quote.total) }} · {{ dateLabel(quote.issued_at) }}</p></details></div></template></dialog>
</CorporateLayout>
</template>

